import{_ as a,o as t,c as r,a0 as n}from"./chunks/framework.D7EjqxMK.js";const f=JSON.parse('{"title":"Agent 评测基准","description":"","frontmatter":{},"headers":[],"relativePath":"06-agent/04_工程实践/04_Agent评测基准.md","filePath":"06-agent/04_工程实践/04_Agent评测基准.md"}'),i={name:"06-agent/04_工程实践/04_Agent评测基准.md"};function o(l,e,g,c,h,p){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="agent-评测基准" tabindex="-1">Agent 评测基准 <a class="header-anchor" href="#agent-评测基准" aria-label="Permalink to &quot;Agent 评测基准&quot;">​</a></h1><blockquote><p><strong>在知识图谱中的位置</strong>：模块四 · 04_工程实践 · 第 4 节 <strong>难度</strong>：⭐⭐ | <strong>前置知识</strong>：Agent 基础</p></blockquote><hr><h2 id="_1-主流评测基准" tabindex="-1">1. 主流评测基准 <a class="header-anchor" href="#_1-主流评测基准" aria-label="Permalink to &quot;1. 主流评测基准&quot;">​</a></h2><h3 id="agentharm-iclr-2025" tabindex="-1">AgentHarm (ICLR 2025) <a class="header-anchor" href="#agentharm-iclr-2025" aria-label="Permalink to &quot;AgentHarm (ICLR 2025)&quot;">​</a></h3><p>AgentHarm 是衡量 LLM Agent 有害性的基准，发表于 ICLR 2025。<a href="https://proceedings.iclr.cc/paper_files/paper/2025/file/c493d23af93118975cdbc32cbe7323f5-Paper-Conference.pdf" target="_blank" rel="noreferrer">来源: AgentHarm (ICLR 2025)</a></p><h3 id="openagentsafety-iclr-2026" tabindex="-1">OpenAgentSafety (ICLR 2026) <a class="header-anchor" href="#openagentsafety-iclr-2026" aria-label="Permalink to &quot;OpenAgentSafety (ICLR 2026)&quot;">​</a></h3><p>OpenAgentSafety 是全面评估真实世界 AI Agent 安全的框架，发表于 ICLR 2026，由 Carnegie Mellon 等机构提出。<a href="https://openreview.net/pdf?id=xggSxCFQbA" target="_blank" rel="noreferrer">来源: OpenAgentSafety (ICLR 2026)</a></p><h3 id="agentthreatbench" tabindex="-1">AgentThreatBench <a class="header-anchor" href="#agentthreatbench" aria-label="Permalink to &quot;AgentThreatBench&quot;">​</a></h3><p>UK Government BEIS 的 AgentThreatBench，基于 OWASP Top 10 for Agentic Applications 实现。<a href="https://github.com/UKGovernmentBEIS/inspect_evals/issues/1031" target="_blank" rel="noreferrer">来源: AgentThreatBench (GitHub)</a></p><h3 id="agentbench" tabindex="-1">AgentBench <a class="header-anchor" href="#agentbench" aria-label="Permalink to &quot;AgentBench&quot;">​</a></h3><p>通用 Agent 评测基准，测试多轮任务完成度。<a href="https://github.com/THUDM/AgentBench" target="_blank" rel="noreferrer">来源: AgentBench</a></p><hr><h2 id="_2-owasp-agentic-ai-top-10-已验证来源" tabindex="-1">2. OWASP Agentic AI Top 10（已验证来源） <a class="header-anchor" href="#_2-owasp-agentic-ai-top-10-已验证来源" aria-label="Permalink to &quot;2. OWASP Agentic AI Top 10（已验证来源）&quot;">​</a></h2><p>OWASP 发布了针对 Agentic Applications 的 Top 10 安全风险标准。<a href="https://genai.owasp.org/2025/12/09/owasp-top-10-for-agentic-applications-the-benchmark-for-agentic-security-in-the-age-of-autonomous-ai/" target="_blank" rel="noreferrer">来源: OWASP GenAI</a></p><p><strong>十大风险</strong>：</p><ol><li>工具滥用（Tool Abuse）</li><li>提示注入（Prompt Injection）</li><li>越狱攻击（Jailbreak）</li><li>数据泄露（Data Exfiltration）</li><li>幻觉执行（Hallucinated Actions）</li><li>权限逃逸（Privilege Escalation）</li><li>无限循环/资源耗尽</li><li>供应链攻击</li><li>审计缺失</li><li>伦理与偏见</li></ol><p><a href="https://genai.owasp.org/download/45674/" target="_blank" rel="noreferrer">来源: OWASP Agentic AI 报告 (v1.1, Dec 2025)</a></p><hr><h2 id="_3-参考资料" tabindex="-1">3. 参考资料 <a class="header-anchor" href="#_3-参考资料" aria-label="Permalink to &quot;3. 参考资料&quot;">​</a></h2><ul><li><a href="https://proceedings.iclr.cc/paper_files/paper/2025/file/c493d23af93118975cdbc32cbe7323f5-Paper-Conference.pdf" target="_blank" rel="noreferrer">AgentHarm (ICLR 2025)</a></li><li><a href="https://openreview.net/pdf?id=xggSxCFQbA" target="_blank" rel="noreferrer">OpenAgentSafety (ICLR 2026)</a></li><li><a href="https://genai.owasp.org/2025/12/09/owasp-top-10-for-agentic-applications-the-benchmark-for-agentic-security-in-the-age-of-autonomous-ai/" target="_blank" rel="noreferrer">OWASP Top 10 for Agentic Applications</a></li><li><a href="https://genai.owasp.org/download/45674/" target="_blank" rel="noreferrer">OWASP Agentic AI 报告</a></li><li><a href="https://github.com/UKGovernmentBEIS/inspect_evals/issues/1031" target="_blank" rel="noreferrer">AgentThreatBench (GitHub)</a></li><li><a href="https://github.com/THUDM/AgentBench" target="_blank" rel="noreferrer">AgentBench</a></li><li><a href="https://huggingface.co/blog/royswastik/evaluating-agentic-ai-part-4-security" target="_blank" rel="noreferrer">Part 4: Security Evaluation of Agentic AI Systems (Hugging Face)</a></li></ul>',21)])])}const A=a(i,[["render",o]]);export{f as __pageData,A as default};
